BEGIN;
SET LOCAL search_path = public;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (215::BIGINT, 'Bastante buena la verdad, full recomendada.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2026-07-23T00:00:00+00:00'::TIMESTAMPTZ, 'e12b07c1f7a45127c42e4bd2992fbd3e4e1e31b2e328f02b22a47abcea15e6cc'::TEXT, ARRAY[607]::BIGINT[]),
    (215::BIGINT, 'La profe es muuuuy buena, es un amor de persona. Se preocupa mucho para que cada estudiante entienda los contenidos. Sin duda es una excelente opción para llevar el curso, eso sí, al ser verano tiene que ponerle con el autoestudio. Califica suave pero tampoco regala puntos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador']::TEXT[], '2026-04-16T00:00:00+00:00'::TIMESTAMPTZ, '8f4c698b2809abe75560c65a62bfee1961c461ca82cdade100f0c7eebbdc3eb0'::TEXT, ARRAY[922]::BIGINT[]),
    (215::BIGINT, 'Muy amable, organizada, ayuda bastante, sin embargo sí hay que practicar muchos problemas por aparte, no sé como hay comentarios que dicen que es pésima profesora, ya que, sí explica bien la materia.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2025-12-09T00:00:00+00:00'::TIMESTAMPTZ, '3c11670e5d083da812742045b9713837572b429b2b54e769212c8a9b991c84ce'::TEXT, ARRAY[922]::BIGINT[]),
    (215::BIGINT, 'Lo llevé virtual. Es buena profe para la parte teórica, pero casi no hace ejercicios, entonces hay que practicar mucho por aparte. La profe sí brinda ayuda sí se lo pide y siempre tiene buena actitud hacia los "reclamos" de evaluaciones. Los quices son fáciles si estudia. Califica justo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Aspectos de calificación claros']::TEXT[], '2025-12-06T00:00:00+00:00'::TIMESTAMPTZ, '105e1985ed46c1555947f3cc286ffc7e29e13149ba6cb23ec86902abfb43f221'::TEXT, ARRAY[922]::BIGINT[]),
    (215::BIGINT, 'Es muy buena profe, aunque si lo van a llevar virtual tomen en cuenta que ella solo hace una clase sincronica a la semana entonces hay que ser autodidacta. Me gusta que es super responsable y puntual, revisa los examenes/tareas y constesta dudas super rapido. Recomendadisima'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2025-06-23T00:00:00+00:00'::TIMESTAMPTZ, '36d87f968874e3212080cbf8d25a90f637247e46076b0d7b8aadc6af84f4ae9d'::TEXT, ARRAY[922]::BIGINT[]),
    (215::BIGINT, 'Es muy fácil pasar física 3, la profe califica muy suave. Yo para el segundo y tercer examen no estudié nada y pegué más de 80 en ambos porque el curso se pasa viendo ejercicios resueltos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2025-02-25T00:00:00+00:00'::TIMESTAMPTZ, '3592328ae42d1ef014a74bb0c87cfd6c4aa8982af1683e6c1b0100e9c88fdea0'::TEXT, ARRAY[922]::BIGINT[]),
    (215::BIGINT, 'Es muy linda persona y se interesa bastante en ayudarlo a uno. Califica normal tirando a suave. Explica bien la parte conceptual, pero casi no hace ejercicios, entonces uno ocupa ser autodidacta sí o sí para ir bien. Bastante bien para verano, en semestre lo pensaría más, pero nada qué temer'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2025-02-04T00:00:00+00:00'::TIMESTAMPTZ, '2854a19e88c7a451620d10e714c6d46c259afb2a75823839ba0084ba580eb369'::TEXT, ARRAY[922]::BIGINT[]),
    (215::BIGINT, 'La profe es un amor, pero a la hora de explicar queda debiendo un poco. Casi no hace ejercicios y sus explicaciones de la materia son muy superficiales, aún así siempre está súper pendiente al atender dudas fuera de clase. Si usted no es autodidacta, descártela del todo. Califica suave, lo justo'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2025-02-03T00:00:00+00:00'::TIMESTAMPTZ, '71bcc5e4a69e63796e6de2cd583e02d58ffcec51d4b0b2b23f9a2c44fbc62c55'::TEXT, ARRAY[922]::BIGINT[]),
    (215::BIGINT, 'Ella es un amor de persona, ayuda mucho, se ve que quiere ser buena profe. En verano ha sido medio chill la verdad, a veces mete varas voladas, nada que ver con lo que uno ve en clase, pero a pesar de, es muy fácil pasar.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2025-01-23T00:00:00+00:00'::TIMESTAMPTZ, '7f17e4552a95c88490d087d231caebedc0ab52fafa513fe4c4656b8f055ee81f'::TEXT, ARRAY[922]::BIGINT[]),
    (215::BIGINT, 'La profe da muy buena retroalimentación para las entregas, así que el que pierdes puntos en realidad es porque no le pide ayuda. Me parece una persona agradable, el curso es tedioso pero se pasa bien con ella.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-27T00:00:00+00:00'::TIMESTAMPTZ, '1cd9db93ebf5a9a6dfc7eca085f346dbf4a20c9c2b8dd4c7342bc4a7b7ae8974'::TEXT, ARRAY[607]::BIGINT[]),
    (215::BIGINT, 'La profe es agradable, se confunde con una estudiante más y era muy amable, pero a la hora de calificar lo hacía ridículamente duro . No ayudaba nada en los trabajos, instrucciones confusas y cuando revisaba ponía cosas malas y ni ella sabía por qué. No la recomiendo, muy intensa con la asistencia.'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2024-11-23T00:00:00+00:00'::TIMESTAMPTZ, '1129a0ab9c03226933e28318cd14db4a33e6ace02ced9d074b06770307a106de'::TEXT, ARRAY[607]::BIGINT[]),
    (215::BIGINT, 'Creo que intenta tapar desconocimiento evaluando durísimo, pero ella se hace bola explicando conceptos básicos en la clase. Entonces es lo peor de todos los mundos. No es buen profe que califica duro, ni mal profe que califica suave. Con ella se tira el curso por la ventana si o si.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2024-05-05T00:00:00+00:00'::TIMESTAMPTZ, 'b25e8e9c15c16afa1a7792d24e258ff6b15d02f6f0c7de54bad2f5649b407d84'::TEXT, ARRAY[922]::BIGINT[]),
    (215::BIGINT, 'Siganla en Insta, vale la pena: @anelev_r La profe se enreda mucho y no explica bien. Solo ve lo más básico y teórico; y no hace ejercicios. Sus clases son cortas y aburrida.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2023-10-15T00:00:00+00:00'::TIMESTAMPTZ, 'e503eb385d9452a73b5c10f913d271398ba91a55d62b508ed849aefbc36e3dbc'::TEXT, ARRAY[604]::BIGINT[]),
    (215::BIGINT, 'Llevé con esta profesora modalidad virtual, las clases son cortas, daba una sola clase por semana con la excusa de que nosotros teniamos que leer los documentos de catedra por nuestra cuenta y no los explicaba, 1-2 ejemplos MUY BASICOS por clase. No responde mensajes ni ayuda (tampoco en consulta)'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2023-07-16T00:00:00+00:00'::TIMESTAMPTZ, 'a8f2ad502859a409a80450837c45534521c20b4ca0ff56762819db7611a970b7'::TEXT, ARRAY[604]::BIGINT[]),
    (215::BIGINT, 'Daba una clase sincrónica una vez a la semana pero solo "explicaba" teoría simple. Los ejercicios de tarea eran muchísimo más complejos que cualquier cosa vista en clase. Tardó demasiado en calificar los trabajos. La clase fue prácticamente autodidacta pero ella califica como si enseñara algo.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '049a7d77d33d240aeb1ce93d25f2a8ea7ac4a3c4c526b21c5c4f481784845f54'::TEXT, ARRAY[3257]::BIGINT[]),
    (215::BIGINT, 'Explica lo justo y neceasrio para hacer las prácticas; a veces está bien pero muchas veces era confuso algunas cosas. Está bien para este curso, como persona es un amor y cae super bien; parece una estudiante más. Califica al pie de la letra de la rúbrica de la cátedra y al final de semestre.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '6904a763a17069539e30edac926cd26fcdcf43e159f32d6186ec60993b6585d9'::TEXT, ARRAY[631]::BIGINT[]),
    (215::BIGINT, 'Explica bien, en el laboratorio ayuda bastante, pero para el formato y realizacion del informe no ayuda mucho su explicacion, aconsejo que para eso use material de la catedra, si no se lo suena en los informe. Agradable, fue en patines a dar una clase y cuidado con confundirla con una companera'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2022-12-22T00:00:00+00:00'::TIMESTAMPTZ, 'de5f5e4fa9179ff19c0475939f2c11e485006c9ae1f5f2c9a4c2e42db86200d9'::TEXT, ARRAY[607]::BIGINT[]),
    (215::BIGINT, 'Es una profe amable pero casi nunca ve ejercicios útiles el curso sin embargo el curspose puede sacar adelante con lo que sube la catedra. Si usted es una persona autodidacta matricular con ella le puede servir .'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-22T00:00:00+00:00'::TIMESTAMPTZ, '84c67eccf8828dc0886e9a395039c9c777a005600e6514e8711141cfc0a83518'::TEXT, ARRAY[922]::BIGINT[]),
    (215::BIGINT, 'Miren no quisiera ser malo, pero ella es pésima, todo el curso a pura cátedra, no trata bien a los estudiantes, la asistencia es bruscamente obligatoria, califica muy lento, no se le puede contactar fuera de consulta, es estricta e intensa y no llegas a interesarte mucho en las clases. CON ELLA NO!!'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2022-11-09T00:00:00+00:00'::TIMESTAMPTZ, 'c0fef85cf40a762557cae866dc30697da0c3c890bf81982c3811240a611cbec0'::TEXT, ARRAY[631]::BIGINT[]),
    (215::BIGINT, 'Es amable como persona, como profe nos explicaba una clase la teoría, y la otra clase nos dejaba ejercicios que nunca entendí con lo que nos explicaba. Dura un poco en responder para consultas, y con las bitácoras duró mucho para entregarlas. En lo practico ni tuve tanta ayuda como hubiera querido.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'a6ef7c4eaff7220403eafcbb4f6d5243f0a5203d75b5c2c046033fa3645fd249'::TEXT, ARRAY[3257]::BIGINT[]),
    (215::BIGINT, 'La profe es muy amable, pero apenas hace ejemplos lo cual no es de mucha ayuda al momento de realizar las evaluaciones.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, '84d49d1559ad0b00baf82749a3fe097ebb2405050ddbeb9a52f479a769cb4e12'::TEXT, ARRAY[3257]::BIGINT[]),
    (215::BIGINT, 'Es calidad de profesora!! Explica muy bien; las clases son completas, inspiracionales, y sirven de excelente utilidad al material que brinda la cátedra. Contesta las dudas muy rápido, y es una muy linda persona!! La recomiendo 100%!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Clases excelentes']::TEXT[], '2022-06-17T00:00:00+00:00'::TIMESTAMPTZ, '05493afd01c16a311b47dd1f38ac63840252150ec917585879a4c0ab7c49f628'::TEXT, ARRAY[922]::BIGINT[]),
    (215::BIGINT, 'Es un despiche. Califica todo hasta semana 18 por lo cual uno no tiene retroalimentación en el curso. Tarda años en contestar correos. Las clases son solo de repaso, uno depende del material de la cátedra o de ir a clases con otros profes. Si no es autodidacta no lo va a lograr'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'e489ff8057cd0db77a5c15d595349ac58b7290b0dc36d77e2f5410bccbdbcda2'::TEXT, ARRAY[922]::BIGINT[]),
    (215::BIGINT, 'La profe es muy amable, sin embargo solo explica teoría y no los ejercicios, por lo que el curso es casi 100% autodidacta, ademas de 2 clases da solo 1 a la semana, entonces siento que no se hace tan provechoso. Si le cuesta la fisica huya.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2022-06-10T00:00:00+00:00'::TIMESTAMPTZ, '5840d6e4360a9f37f4fbbe417efdff715f3f554e4ae52ea0b14ed6d5090013d2'::TEXT, ARRAY[3257]::BIGINT[]),
    (215::BIGINT, 'Buena profesora. Explica lo necesario para realizar cada una de las evaluaciones, atenta a consultas, califica normal y en general, super recomendada para este lab.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-25T00:00:00+00:00'::TIMESTAMPTZ, '4990faa306c7dc68b1f467b4a4d2c5a3e2b26912fd911ac848c49415a92d5e8a'::TEXT, ARRAY[607, 631]::BIGINT[]),
    (215::BIGINT, 'Califica muy duro, no da suficientes instrucciones y entrega todas las notas a final de semestre'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'd9c7874772dd69cab73c5c90aa10c77b25c3f282c7a3f06c5e07afefc1bcf8b1'::TEXT, ARRAY[607]::BIGINT[]),
    (215::BIGINT, 'El curso (en virtual) se pasa solo, pero ella se saca instrucciones que nunca da y solo espera que uno sepa'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, '3bd6047dee2ebc865f0ce29e3f8ed76e428551548c203553384946bbf94eae8c'::TEXT, ARRAY[607]::BIGINT[]),
    (215::BIGINT, 'Las clases no siempre son de gran ayuda. Si se necesita aclarar una duda es mejor preguntar con tiempo porque tarda en contestar.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'c043c27244ed820ba2ad634dc053f6a4b2f1dfee03e1316d010a1896ab6c4879'::TEXT, ARRAY[607]::BIGINT[]),
    (215::BIGINT, 'La profe se enreda mucho y sus clases no son de gran ayuda, si uno necesita ayuda tiene que hacerlo con tiempo porque suele tardar en contestar.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'd9f3dcc873082b8d61535956aee36ef15610b730d0abfb52e737b4b437947db3'::TEXT, ARRAY[607]::BIGINT[]),
    (215::BIGINT, 'Es una buena profe, califica suave y se entienden las instrucciones de los trabajos. Casi todo es con cátedra entonces no es para nada dificil de pasar.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, '044b14eafb379943da6ee0371ccf7e6bfe6a748e8e733f856a514c9103830b38'::TEXT, ARRAY[607]::BIGINT[]),
    (215::BIGINT, 'Pésima profesora. Siempre llegaba tarde a la clase y explica por encimita. Solo ve teoría. Cuando nos acercábamos al examen y no habíamos hecho ni un solo ejercicio se ponía a copiar como loca unos ejercicios que ya estaban resueltos. No la recomiendo.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-16T00:00:00+00:00'::TIMESTAMPTZ, '8c9a4bddd8c49d83cde66794997bf89c48bc87f24fcd444bbf033e91665c44b0'::TEXT, ARRAY[604]::BIGINT[]),
    (215::BIGINT, 'Es regular, para lab esta bien explica "claro" y califica muy suave a mi parecer. Todo es con la catedra entonces se hace muy llevadero'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, '489705e89eecd84f69dca3e9d4e6bb2a2381b5922ac68fa1bcaccdbab7e154e5'::TEXT, ARRAY[607]::BIGINT[]),
    (215::BIGINT, 'Curso bastante fácil, las clases son cortas y explica bien. Responde dudas solo por Teams pero dura algunos días'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, '198d4a97c94a7117defbaaa61758e259a983b1ec48275eb08e910da149a4c12d'::TEXT, ARRAY[607]::BIGINT[]),
    (215::BIGINT, 'El curso es muy fácil de pasar virtual. Los trabajos son simples y no quitan mucho tiempo. Para los quices siempre es bueno leer la materia de la semana, las preguntas salen de ahí. Buena opción para matricular'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-25T00:00:00+00:00'::TIMESTAMPTZ, 'db148c6a9da8a430477132a4a3d6abbb42834232c8eac7c7cc2cc29542b46b95'::TEXT, ARRAY[607]::BIGINT[]),
    (215::BIGINT, 'Perfecta profe, explica muy bien y ayuda bastante. Responde correos y ayuda bastante'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-11-20T00:00:00+00:00'::TIMESTAMPTZ, '95befa5a3f9bc75c9d8914a0f59aa47516d918641c6abc7449322037d54fac49'::TEXT, ARRAY[607]::BIGINT[]),
    (215::BIGINT, 'Muy buena profe en general, explica bastante bien Sin embargo, en las clases virtuales no estuvo muy presente en las clases sincrónicas, pero el curso se pasa'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, 'ce035528da0f6267d7f1ba330bcc4f255bfabc6c416740e6678b7125b1c13657'::TEXT, ARRAY[607]::BIGINT[]),
    (215::BIGINT, 'Con la modalidad virtual no se sintió mucha cercanía con los estudiantes. Sin embargo, si usted pide ayuda y lee bien las instrucciones el curso es fácil de pasar. No dura mucho en contestar los correos. Lo único de lo que me quejo es que dio todas las notas hasta el final del semestre.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '07c52c78f5a8305862443650fcffe582b220a043adf4f9ffb2addec216cfe227'::TEXT, ARRAY[607]::BIGINT[]),
    (215::BIGINT, 'Es muy buena como persona. Cuando se volvió virtual, dejó videos de You Tube y pueden llegar a ser complicados los trabajos que deja. Creo que le responde más rápido por correo que por el Teams. Calificó todo hasta el final. Manda un correo cuando se equivoca o recordar algún trabajo.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, '81ca03285758c0891ca803826e8722a0cbceee44b8a9bf29149507820a823afe'::TEXT, ARRAY[3257]::BIGINT[]),
    (215::BIGINT, 'Todo es asincrónico, me tocaba pedir videos de otros profes de lab porque ella no apoyaba entonces uno no sabía si lo que hacía estaba bien, y duraba mucho en contestar correos, las primeras calificaciones super rudas, ya luego salí bastante bien pero hay que buscar ayuda'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'ef7759ca80cae46867a5b5f2ab22dca3408e71b1a658db0265fa8b1cf43438eb'::TEXT, ARRAY[631, 607]::BIGINT[]),
    (215::BIGINT, 'Deja demasiadas evaluaciones y califica súper duro, no explica nada, dura mucho contestando dudas, todas las clases son asincrónicas y solo deja la presentación y unos videos de youtube para suplir la materia de cada semana, nada de retroalimentación, ni siquiera logró ver todos los temas del curso.'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'e769bd5dd4e0959607c2146f21c68aad649d136aadc44f996e17fc70a5abe47f'::TEXT, ARRAY[3257]::BIGINT[]),
    (215::BIGINT, 'Se enfocaba demasiado en teoría y dejó la práctica. Cuando nos pasamos a virtual asincrónico fue un abandono. Las evaluaciones no se podían contestar con la explicación dada de la materia. No hay retroalimentación, calificaba hasta el final. Usaba videos de youtube para dar materia y no explicar.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Aspectos de calificación claros']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '5dfbe97ff71205f81396b8f10dc936913b85f6c132863c5e9f0a3aba94203b27'::TEXT, ARRAY[3257]::BIGINT[]),
    (215::BIGINT, 'Muy desordenada, se equivoca mucho y califica hasta el final. Es decir no hay retroalimentación'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2020-08-09T00:00:00+00:00'::TIMESTAMPTZ, 'd02e6733a640136ffb2d9c3de9698a6eae824b4ac37242f8b4ce48e8a48198db'::TEXT, ARRAY[3257]::BIGINT[]),
    (215::BIGINT, 'En virtual nos abandonó, no contesta dudas de manera clara. Manda muchas evaluaciones. Pide lo máximo y da lo mínimo, es como estar sin profesor y hacer todo por cuenta propia.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2020-08-04T00:00:00+00:00'::TIMESTAMPTZ, '3df8822c94bf5ca260b12e2c1d80774b68e576694d01aaa559017a133a206e55'::TEXT, ARRAY[3257]::BIGINT[]),
    (215::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2020-07-28T00:00:00+00:00'::TIMESTAMPTZ, 'ac4d2975d99bbd041190e2e7393dab887bf92e4014a1428408b7fd81475fb206'::TEXT, ARRAY[3257]::BIGINT[]),
    (215::BIGINT, 'En clases virtuales fue como si no hubiera profesor. No acepta recomendaciones, y las clases fueron muy ausentes. Deja demasiados trabajos y solo pone videos de YouTube que “explican” la materia.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2020-07-28T00:00:00+00:00'::TIMESTAMPTZ, '55011f0a41b0784ad870df6f4672deba6eea1c30893c736c19187932a529a17b'::TEXT, ARRAY[3257]::BIGINT[]),
    (215::BIGINT, 'Ella es muy buena gente. La clase es aburrida y no siempre es clara, aunque le intenta hacer entretenido en presencial. Desorganizada. En la virtualización se sintió como un abandono y no responde a correos. En virtual pide mucho y da lo mínimo.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2020-07-28T00:00:00+00:00'::TIMESTAMPTZ, '12cad816c5c509a578ab317e494d9d982422b0e6b9eae2e696dfc89e0f406a9e'::TEXT, ARRAY[3257]::BIGINT[]),
    (215::BIGINT, 'Es buena profe, pero se enfoca mucho en la teoría y no tanto en la práctica. Es agradable, pero si uno le manda un correo solicitando ayuda o consulta no contesta los correos. Y en persona, a veces las dudas no las contesta muy claro.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'faa34e42b5447c7813da209766f7a74e39d01bd91f58c7e7eb087bff73575e1e'::TEXT, ARRAY[604]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
